E removeAt(int i) {

        final Object[] es = queue;
        modCount++;
        int s = --size;
        if (s == i) 
            es[i] = null;
        else {
            E moved = (E) es[s];
            es[s] = null;
            siftDown(i, moved);
            if (es[i] == moved) {
                siftUp(i, moved);
                if (es[i] != moved)
                    return moved;
            }
        }
        return null;
    }
